/**
 * Narrows an error thrown by a token request method to one caused by an `mfa_required` response.
 *
 * When the Auth0 server requires multi-factor authentication, token request methods
 * (`getTokenByPassword`, `getTokenByRefreshToken`, `exchangeToken`, `passkey.getTokenByPasskey`,
 * `getTokenByPasswordlessEmail`, `getTokenByPasswordlessSms`) throw their usual error
 * (e.g. `TokenByPasswordError`, `PasswordlessVerifyError`) with `cause.error` set to `'mfa_required'`.
 * The `cause` will also contain:
 * - `mfa_token` — the token needed to proceed with enrollment or challenge MFA APIs
 * - `mfa_requirements` — (optional) describes which factors to challenge or enroll
 *
 * This type guard checks whether an error was caused by an `mfa_required` response and
 * narrows the type so that `cause` and `cause.mfa_token` are guaranteed to be defined.
 *
 * @param error - The error caught from a token request method
 * @returns `true` if the error was caused by an `mfa_required` server response
 *
 * @example
 * ```typescript
 * import { AuthClient, isMfaRequiredError } from '@auth0/auth0-auth-js';
 *
 * try {
 *   await authClient.getTokenByPassword({ username, password });
 * } catch (error) {
 *   if (isMfaRequiredError(error)) {
 *     // error.cause.mfa_token is guaranteed to be defined here
 *     const challenge = await authClient.mfa.challengeAuthenticator({
 *       mfaToken: error.cause.mfa_token,
 *       challengeType: 'otp',
 *     });
 *   }
 * }
 * ```
 */
export interface MfaRequiredError extends Error {
  code: string;
  cause: OAuth2Error & { error: 'mfa_required'; mfa_token: string; mfa_requirements?: MfaRequirements };
}

export function isMfaRequiredError(error: unknown): error is MfaRequiredError {
  return (
    error instanceof Error &&
    (error as { cause?: OAuth2Error }).cause?.error === 'mfa_required' &&
    typeof (error as { cause?: OAuth2Error }).cause?.mfa_token === 'string'
  );
}

/**
 * Error thrown when calling a method that is not supported in Enterprise Connect mode.
 * Enterprise Connect uses Auth0 as a pure SSO relay — no Auth0 session or refresh token
 * is created, so session-dependent operations are invalid.
 */
export class EnterpriseConnectNotSupportedError extends Error {
  public code: string = 'enterprise_connect_not_supported';

  constructor(methodName: string) {
    super(
      `"${methodName}" is not supported in Enterprise Connect mode. ` +
        'Auth0 acts as a pure SSO relay and does not manage a session or issue refresh tokens.'
    );
    this.name = 'EnterpriseConnectNotSupportedError';
  }
}

/**
 * Error thrown when Client Secret or Client Assertion Signing Key is missing.
 */
export class MissingClientAuthError extends Error {
  public code: string = 'missing_client_auth_error';

  constructor() {
    super('The client secret or client assertion signing key must be provided.');
    this.name = 'MissingClientAuthError';
  }
}

/**
 * Error thrown when the organization claim (`org_id` or `org_name`) in the
 * returned ID token does not match the organization requested at login.
 *
 * This is a post-exchange claim-validation failure — the token request itself
 * succeeded. It therefore extends plain `Error` and does not carry an OAuth2
 * error cause.
 */
export class OrganizationValidationError extends Error {
  public code: string = 'organization_validation_error';

  constructor(message: string) {
    super(message);
    this.name = 'OrganizationValidationError';
  }
}

/**
 * Error thrown when `fullResponse: true` was requested but the HTTP Response
 * was not captured by the capturing fetch wrapper. This indicates an internal
 * bug in the SDK's response-capture mechanism.
 */
export class MissingCapturedResponseError extends Error {
  public code: string = 'missing_captured_response_error';

  constructor(message?: string) {
    super(
      message || 'fullResponse: true requested but no HTTP Response was captured. This is a bug in CapturingFetch.'
    );
    this.name = 'MissingCapturedResponseError';
  }
}
